SELECT sm.sm_ship_mode_id, sm.sm_type, SUM(cr.cr_return_amount) AS total_return_amount, SUM(ws.ws_net_profit) AS total_net_profit FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN web_sales ws ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE cr.cr_returned_date_sk = 2450996 AND ws.ws_sold_date_sk = 2451328 GROUP BY sm.sm_ship_mode_id, sm.sm_type
